import sys
def pattern(n):
    lines = []
    c = 0
    for i in range(1, n + 1):
        lines.append(chr(65 + c) * i)
        c += 1
    for i in range(n - 1, 0, -1):
        lines.append(chr(65 + c) * i)
        c += 1
    return '\n'.join(lines)
def main():
    s = sys.stdin.read().strip()
    if s:
        print(pattern(int(s)))
main()

